import sys

import Pyro4
from hran_elementmanager2g.pyro_server import PyroServer
from hran_elementmanager2g.trace_capture import TraceCapture, SysLog
from hran_elementmanager2g.utils.constants import (DAEMON_HOST, DAEMON_PORT_TRACES, PYRO_SERVER_NAME_TRACES,
                                                   SERVER_VERSION, PYRO_LOGFILE, PYRO_LOGLEVEL, SERIALIZERS_ACCEPTED)
from hran_elementmanager2g.wrapper import OutputHandler

Pyro4.PYRO_LOGFILE = PYRO_LOGFILE
Pyro4.PYRO_LOGLEVEL = PYRO_LOGLEVEL
Pyro4.config.SERIALIZERS_ACCEPTED = SERIALIZERS_ACCEPTED
Pyro4.config.REQUIRE_EXPOSE = False


class PyroServerTraces(PyroServer, OutputHandler):

    def __init__(self, pyro_port=DAEMON_PORT_TRACES):
        print('running as traces capture server')
        self.pyro_port = pyro_port
        sys.stdout = OutputHandler()
        self.uri = None
        self.server_version = SERVER_VERSION
        self.running = True
        self.tc = None
        self.sl = None
        self.daemon = None

    def start_server(self, host_ip=DAEMON_HOST):
        with Pyro4.Daemon(host=host_ip, port=self.pyro_port) as daemon:
            self.uri = daemon.register(self, objectId=PYRO_SERVER_NAME_TRACES)
            self.running = True
            self.daemon = daemon
            print("element_manager_pyro_server_TRACES_running")
            daemon.requestLoop()

    def trace_cap(self, board_type, trace_type):
        self.tc = TraceCapture()
        return self.tc.start_traces(board_type, trace_type)

    def trace_cap_stop(self):
        return self.tc.stop_traces()

    def syslog_cap(self):
        self.sl = SysLog()
        return self.sl.start_syslog_traces()

    def syslog_cap_stop(self):
        return self.sl.stop_syslog_traces()


if __name__ == '__main__':
    if len(sys.argv) == 2:
        traces_server = PyroServerTraces(pyro_port=int(sys.argv[1]))
        print('starting pyro server as traces capture instance...')
        traces_server.start_server()
        print('server daemon for traces closed')
    else:
        print('wrong or incomplete parameters for traces_server!')
        print('command line interface syntax:')
        print('server_runner.py <pyro_port>')
